using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using Unity.Collections;
public static class CityMobileMeshReducer {
public sealed class Data {public Vector3[] p,n;public Vector4[] tangent;public Color[] colors;public List<Vector4>[] uv=new List<Vector4>[8];public int[][] triangles;}
public static long Triangles(Mesh m){long t=0;for(int i=0;i<m.subMeshCount;i++)t+=(long)m.GetIndexCount(i)/3;return t;}
public static Data Read(Mesh m){var d=new Data();using(var data=Mesh.AcquireReadOnlyMeshData(m)){var v=data[0];int count=v.vertexCount;using(var a=new NativeArray<Vector3>(count,Allocator.Temp)){v.GetVertices(a);d.p=a.ToArray();if(m.HasVertexAttribute(VertexAttribute.Normal)){v.GetNormals(a);d.n=a.ToArray();}}using(var a=new NativeArray<Vector4>(count,Allocator.Temp)){if(m.HasVertexAttribute(VertexAttribute.Tangent)){v.GetTangents(a);d.tangent=a.ToArray();}for(int k=0;k<8;k++)if(m.HasVertexAttribute(VertexAttribute.TexCoord0+k)){v.GetUVs(k,a);d.uv[k]=a.ToArray().ToList();}}if(m.HasVertexAttribute(VertexAttribute.Color)){using(var a=new NativeArray<Color>(count,Allocator.Temp)){v.GetColors(a);d.colors=a.ToArray();}}d.triangles=new int[m.subMeshCount][];for(int k=0;k<m.subMeshCount;k++){using(var a=new NativeArray<int>((int)m.GetIndexCount(k),Allocator.Temp)){v.GetIndices(a,k,true);d.triangles[k]=a.ToArray();}}}return d;}
// Conservative vertex clustering for distant copies only. UV islands, atlas tiles,
// hard-normal regions and all auxiliary vertex channels remain separated.
public static string LastReason; public static Mesh Reduce(Mesh source,int level){LastReason="";var d=Read(source);int count=d.p.Length;float span=Mathf.Max(source.bounds.size.x,source.bounds.size.y,source.bounds.size.z);float cell=Mathf.Max(.00001f,span*(level==1?.008f:.025f));int uvPrecision=level==1?16:8;var groups=new Dictionary<string,int>();var orig=new List<int>();var sums=new List<Vector3>();var weights=new List<int>();var remap=new int[count];for(int i=0;i<count;i++){var p=d.p[i];var n=d.n!=null?d.n[i]:Vector3.up;string key=Mathf.RoundToInt(p.x/cell)+","+Mathf.RoundToInt(p.y/cell)+","+Mathf.RoundToInt(p.z/cell)+"/"+Mathf.RoundToInt(n.x*4)+","+Mathf.RoundToInt(n.y*4)+","+Mathf.RoundToInt(n.z*4);if(d.uv[0]!=null){var t=d.uv[0][i];key+="/"+Mathf.RoundToInt(t.x*uvPrecision)+","+Mathf.RoundToInt(t.y*uvPrecision)+","+t.z+","+t.w;}for(int u=1;u<8;u++)if(d.uv[u]!=null){var t=d.uv[u][i];key+="/u"+u+":"+Mathf.RoundToInt(t.x*uvPrecision)+","+Mathf.RoundToInt(t.y*uvPrecision)+","+t.z+","+t.w;}if(d.colors!=null)key+="/c"+d.colors[i].ToString("R");int at;if(!groups.TryGetValue(key,out at)){at=orig.Count;groups.Add(key,at);orig.Add(i);sums.Add(p);weights.Add(1);}else{sums[at]+=p;weights[at]++;}remap[i]=at;}
var pos=sums.Select((p,i)=>p/weights[i]).ToList();var pinned=new Dictionary<int,int>();for(int pass=0;pass<12;pass++){bool any=false;foreach(var src in d.triangles)for(int k=0;k<src.Length;k+=3){int a=remap[src[k]],b=remap[src[k+1]],c=remap[src[k+2]];if(a==b||b==c||a==c)continue;var before=Vector3.Cross(d.p[src[k+1]]-d.p[src[k]],d.p[src[k+2]]-d.p[src[k]]);var after=Vector3.Cross(pos[b]-pos[a],pos[c]-pos[a]);if(after.sqrMagnitude<1e-14f||Vector3.Dot(before,after)>0)continue;for(int j=0;j<3;j++){int sourceIndex=src[k+j],at;if(!pinned.TryGetValue(sourceIndex,out at)){at=pos.Count;pinned.Add(sourceIndex,at);pos.Add(d.p[sourceIndex]);orig.Add(sourceIndex);}remap[sourceIndex]=at;}any=true;}if(!any)break;}var triangles=new List<int>[d.triangles.Length];long result=0;for(int sub=0;sub<triangles.Length;sub++){var list=triangles[sub]=new List<int>();var seen=new HashSet<string>();var src=d.triangles[sub];for(int k=0;k<src.Length;k+=3){int a=remap[src[k]],b=remap[src[k+1]],c=remap[src[k+2]];if(a==b||b==c||a==c)continue;var oldN=Vector3.Cross(d.p[src[k+1]]-d.p[src[k]],d.p[src[k+2]]-d.p[src[k]]);var newN=Vector3.Cross(pos[b]-pos[a],pos[c]-pos[a]);if(newN.sqrMagnitude<1e-14f)continue;if(Vector3.Dot(oldN,newN)<=0){LastReason="fold";return null;}int min=Mathf.Min(a,Mathf.Min(b,c));string sig=min==a?a+","+b+","+c:min==b?b+","+c+","+a:c+","+a+","+b;if(!seen.Add(sig))continue;list.AddRange(new[]{a,b,c});}result+=list.Count/3;}
if(result<Triangles(source)*.30||result>Triangles(source)*.95){LastReason="ratio:"+result+" clusters:"+pos.Count+"/"+count;return null;}var used=triangles.SelectMany(t=>t).Distinct().OrderBy(i=>i).ToArray();var compact=new int[pos.Count];for(int i=0;i<used.Length;i++)compact[used[i]]=i;var mesh=new Mesh{name=source.name+" Mobile LOD"+level,indexFormat=used.Length>65535?IndexFormat.UInt32:IndexFormat.UInt16};mesh.SetVertices(used.Select(i=>pos[i]).ToList());if(d.n!=null)mesh.SetNormals(used.Select(i=>d.n[orig[i]]).ToList());if(d.tangent!=null)mesh.SetTangents(used.Select(i=>d.tangent[orig[i]]).ToList());if(d.colors!=null)mesh.SetColors(used.Select(i=>d.colors[orig[i]]).ToList());for(int u=0;u<8;u++)if(d.uv[u]!=null)mesh.SetUVs(u,used.Select(i=>d.uv[u][orig[i]]).ToList());mesh.subMeshCount=triangles.Length;for(int sub=0;sub<triangles.Length;sub++)mesh.SetTriangles(triangles[sub].Select(i=>compact[i]).ToArray(),sub,false);if(d.n==null)mesh.RecalculateNormals();mesh.bounds=source.bounds;mesh.OptimizeIndexBuffers();mesh.OptimizeReorderVertexBuffer();return mesh;}
}
